-- Run ONCE in Supabase SQL Editor: adds RU/EN descriptions to the existing products (nothing is deleted)
update products set description_ru = 'Gamma+ 5555 Turbo Tormalionic — профессиональный фен мощностью 2000–2400 Вт, идеально подходит для процедур кератинового выпрямления. Температура до 179°C, решётка с турмалиновым покрытием и ультраузкая насадка помогают сделать волосы гладкими и блестящими.', description_en = 'Gamma+ 5555 Turbo Tormalionic — a professional 2000–2400 W hair dryer, ideal for keratin treatments. Temperatures up to 179°C, a tourmaline-coated grille and an ultra-narrow nozzle help hair look smooth and shiny.' where slug = '5555';
update products set description_ru = 'Gamma+ MegaCosmo 2500W — мощный фен для профессионального использования. Решётка с турмалиновым покрытием и технология ионизации делают волосы более блестящими и сокращают время сушки.', description_en = 'Gamma+ MegaCosmo 2500W — a powerful dryer for professional use. A tourmaline-coated grille with ionization technology makes hair shinier and shortens drying time.' where slug = 'megacosmo-2500';
update products set description_ru = 'Gamma+ MegaCosmo 2200W — мощный фен для профессионального использования. Решётка с турмалиновым покрытием и технология ионизации делают волосы более блестящими и сокращают время сушки.', description_en = 'Gamma+ MegaCosmo 2200W — a powerful dryer for professional use. A tourmaline-coated grille with ionization technology makes hair shinier and shortens drying time.' where slug = 'megacosmo-2200';
