update products set description_ru = 'Hybrid — качественный и надёжный фен для профессионального использования.', description_en = 'Hybrid — a high-quality, reliable hair dryer for professional use.' where slug = 'hybrid';
update products set description_ru = 'Профессиональный фен мощностью 2500 Вт с сильным потоком воздуха.', description_en = 'A professional 2500 W hair dryer with a powerful airflow.' where slug = 'turbostar';
update products set description_ru = 'Gamma+ XcellS — лёгкий, компактный и мощный профессиональный фен. Удобен в работе, обеспечивает эффективный поток воздуха и высокую производительность.', description_en = 'Gamma+ XcellS — a lightweight, compact and powerful professional hair dryer. Comfortable to use, with efficient airflow and high performance.' where slug = 'xcells';
update products set description_ru = 'Gamma+ X•Hybrid Compact — компактный, лёгкий профессиональный фен с технологией ионизации. Идеальный выбор для удобной работы и эффективной укладки волос.', description_en = 'Gamma+ X•Hybrid Compact — a compact, lightweight professional dryer with ionization technology. An ideal choice for comfortable use and effective styling.' where slug = 'hybrid-mini';
update products set description_ru = 'Gamma+ Plasma — профессиональный фен с технологиями активного кислорода и ионизации: помогает сохранить яркость цвета волос и уменьшить электризацию.', description_en = 'Gamma+ Plasma — a professional dryer with active oxygen and ionization technology that helps preserve hair color vibrancy and reduce static.' where slug = 'plasma';
update products set description_ru = 'Gamma+ Relax Power 2750W — профессиональный фен мощностью 2750 Вт, обеспечивающий сильный поток воздуха и быструю сушку.', description_en = 'Gamma+ Relax Power 2750W — a professional 2750 W dryer delivering strong airflow and fast drying.' where slug = 'relax';
update products set description_ru = 'Профессиональный выпрямитель для волос, идеально подходит для кератиновых процедур. Температура 240°C, керамические пластины, обогащённые алмазной пудрой, и стабильный контроль температуры.', description_en = 'A professional hair straightener, ideal for keratin treatments. 240°C temperature, ceramic plates enriched with diamond powder and stable temperature control.' where slug = 'donna-keratin';
update products set description_ru = 'Gamma+ Keratin Glory — профессиональный выпрямитель для кератиновых процедур. Регулировка температуры 140–230°C, керамические пластины с турмалиновой пудрой и функция автоотключения через 60 минут.', description_en = 'Gamma+ Keratin Glory — a professional straightener for keratin treatments. Adjustable temperature 140–230°C, ceramic plates with tourmaline powder and an automatic shut-off after 60 minutes.' where slug = 'donna-keratin-glory';
update products set description_ru = 'Gamma+ Donna+ Glamour — профессиональный выпрямитель с температурными режимами 170°C, 190°C и 230°C. Керамические пластины, обогащённые алмазной пудрой, придают волосам блеск. Есть функция автоотключения через 30 минут.', description_en = 'Gamma+ Donna+ Glamour — a professional straightener with 170°C, 190°C and 230°C temperature modes. Ceramic plates enriched with diamond powder give hair a glossy shine. Includes an automatic shut-off after 30 minutes.' where slug = 'glamour';
update products set description_ru = 'Gamma+ Iron Clip XL Gold 32 mm — профессиональная плойка для создания локонов. Антистатическое покрытие, регулировка температуры 170–230°C, быстрый нагрев и светодиодный индикатор для безопасной работы.', description_en = 'Gamma+ Iron Clip XL Gold 32 mm — a professional curling iron for creating curls. Antistatic coating, adjustable temperature 170–230°C, fast heat-up and an LED indicator for safe use.' where slug = 'gold-iron-clip-32d';
update products set description_ru = 'Gamma+ Rainbow Antistatic — профессиональный выпрямитель для волос. Антистатическое покрытие снижает электризацию, температура до 230°C и эластичные пластины помогают добиться гладких блестящих волос.', description_en = 'Gamma+ Rainbow Antistatic — a professional hair straightener. The antistatic coating reduces static, while temperatures up to 230°C and flexible plates help create smooth, shiny hair.' where slug = 'rainbow-antistatic';
update products set description_ru = 'Профессиональная конусная плойка. Регулировка температуры 170–210°C, антистатическое покрытие и быстрый нагрев создают объём у корней и мягкие волны на концах. Идеальна для длинных волос.', description_en = 'A professional conical curling iron. Adjustable temperature 170–210°C, antistatic coating and fast heat-up create volume at the roots and soft waves at the ends. Ideal for long hair.' where slug = 'rainbow-g';
update products set description_ru = 'Gamma+ X-Hybrid Cordless — беспроводной профессиональный выпрямитель для волос. 3 температурных режима, пластины с керамическим покрытием и до 30 минут автономной работы для удобного выравнивания волос.', description_en = 'Gamma+ X-Hybrid Cordless — a cordless professional hair straightener. 3 temperature modes, ceramic-coated plates and up to 30 minutes of cordless use for comfortable smoothing.' where slug = 'x-hybrid-cordless';
update products set description_ru = 'Gamma+ Glory iV — профессиональный выпрямитель с инфракрасной технологией и функцией вибрации. Широкие керамико-турмалиновые пластины, регулировка температуры 150–230°C и автоотключение дают гладкие и блестящие волосы.', description_en = 'Gamma+ Glory iV — a professional straightener with infrared technology and a vibration function. Wide ceramic-tourmaline plates, adjustable temperature 150–230°C and an automatic shut-off create smooth, shiny hair.' where slug = 'gamma-glory-iv';
update products set description_ru = 'Gamma+ Rosebud — профессиональный прибор 2-в-1: выпрямитель и стайлер для локонов. Керамические пластины с алмазной пудрой и регулировка температуры 160–220°C создают гладкие волосы и естественные волны.', description_en = 'Gamma+ Rosebud — a professional 2-in-1 straightener and curler. Diamond-powder ceramic plates and adjustable temperature 160–220°C create smooth hair and natural waves.' where slug = 'rosebud';
update products set description_ru = 'Gamma+ Boosted UP — для профессиональной стрижки: мощный мотор 7200 об/мин, нож с DLC-карбоновым покрытием и до 120 минут беспроводной работы. Сменные корпуса и регулируемая система стрижки обеспечивают точный результат.', description_en = 'Gamma+ Boosted UP — for professional haircuts: a powerful 7200 RPM motor, DLC carbon blade and up to 120 minutes of cordless use. Interchangeable housings and an adjustable cutting system deliver precise results.' where slug = 'clipper-boosted-up';
update products set description_ru = 'Gamma+ Shorty — компактная и мощная профессиональная машинка для стрижки. Цифровой бесщёточный мотор 7500 об/мин, нож с DLC-покрытием и до 120 минут беспроводной работы. Идеальный выбор для точной стрижки и удобной работы.', description_en = 'Gamma+ Shorty — a compact and powerful professional hair clipper. 7500 RPM digital brushless motor, DLC-coated blade and up to 120 minutes of cordless use. An ideal choice for precise cutting and comfortable handling.', description_az = 'Gamma+ Shorty — kompakt və güclü peşəkar saç kəsim maşını. 7500 RPM rəqəmsal fırçasız motor, DLC örtüklü bıçaq və 120 dəqiqəyədək simsiz işləmə. Dəqiq kəsim və rahat istifadə üçün ideal seçimdir.' where slug = 'clipper-shorty';
update products set description_ru = 'Gamma+ XCEED — профессиональная беспроводная машинка для стрижки с мотором IN2 Vector. Скорость 8500–11500 об/мин, нож с DLC-покрытием и более 2 часов работы обеспечивают точную стрижку и идеальный результат фейд.', description_en = 'Gamma+ XCEED — a professional cordless hair clipper with an IN2 Vector motor. 8500–11500 RPM speed, a DLC-coated blade and over 2 hours of runtime deliver precise cutting and perfect fade results.' where slug = 'clipper-xceed';
update products set description_ru = 'Gamma+ X-Ergo — машинка для профессиональной стрижки с мощным магнитным мотором 10 000 об/мин. Нож с DLC-покрытием, настраиваемый дизайн и до 120 минут беспроводной работы обеспечивают точную стрижку и идеальный фейд.', description_en = 'Gamma+ X-Ergo — a clipper for professional haircuts with a powerful 10,000 RPM magnetic motor. A DLC-coated blade, customizable design and up to 120 minutes of cordless use deliver precise cutting and perfect fades.' where slug = 'clipper-xergo';
update products set description_ru = 'Gamma+ Boosted Trimmer — профессиональный триммер с мощным мотором 8000 об/мин и T-образным ножом 40 мм с DLC-покрытием. Регулировка длины стрижки 0–0,8 мм, до 120 минут беспроводной работы и сменные корпуса.', description_en = 'Gamma+ Boosted Trimmer — a professional trimmer with a powerful 8000 RPM motor and a 40 mm DLC-coated T-blade. Cutting length adjustable from 0 to 0.8 mm, up to 120 minutes of cordless use and interchangeable housings.' where slug = 'trimmer-boosted';
update products set description_ru = 'Gamma+ XCEED Trimmer — беспроводной триммер для профессиональных контуров и точной стрижки. Мощный мотор IN2 Vector 8500–11500 об/мин, нож с DLC-покрытием и более 2 часов работы дают идеальный результат. Заряжается через USB-C.', description_en = 'Gamma+ XCEED Trimmer — a cordless trimmer for professional outlines and precise cutting. A powerful 8500–11500 RPM IN2 Vector motor, DLC-coated blade and over 2 hours of runtime deliver an ideal result. Charges via USB-C.' where slug = 'trimmer-xceed';
update products set description_ru = 'Gamma+ Hitter Up — беспроводной триммер для профессиональных контуров и точной стрижки. Мощный мотор 7000 об/мин, нож с синим нитрид-титановым покрытием, более 2 часов работы и магнитная крышка для удобной чистки. Зарядка через USB-C.', description_en = 'Gamma+ Hitter Up — a cordless trimmer for professional outlines and precise cutting. A powerful 7000 RPM motor, blue titanium nitride-coated blade, over 2 hours of runtime and a magnetic cover for easy cleaning. USB-C charging.' where slug = 'trimmer-hitter-up';
update products set description_ru = 'Gamma+ Boosted Shaver 2 Foil — электробритва для профессионально чистого бритья и точной финишной обработки. Мощный мотор 11 000 об/мин, гипоаллергенные золотистые титановые сетки и до 120 минут беспроводной работы. Защита IPX7 от воды и зарядка через USB-C.', description_en = 'Gamma+ Boosted Shaver 2 Foil — an electric shaver for a professional close shave and precise finishing. A powerful 11,000 RPM motor, hypoallergenic gold titanium foils and up to 120 minutes of cordless use. IPX7 water resistance and USB-C charging.' where slug = 'boosted-shaver-2-foil';
update products set description_ru = 'Gamma+ Boosted Shaver 1 Foil — электробритва для профессионально чистого бритья и точной финишной обработки. Мощный мотор 8 000 об/мин, гипоаллергенные золотистые титановые сетки и до 120 минут беспроводной работы. Защита IPX7 от воды и зарядка через USB-C.', description_en = 'Gamma+ Boosted Shaver 1 Foil — an electric shaver for a professional close shave and precise finishing. A powerful 8,000 RPM motor, hypoallergenic gold titanium foils and up to 120 minutes of cordless use. IPX7 water resistance and USB-C charging.' where slug = 'boosted-shaver-1-foil';
update products set description_ru = 'Gamma+ Barber Tool Bag — компактная сумка для безопасной переноски и аккуратного хранения барберских инструментов. Материал устойчив к ударам, воде и пыли, два внутренних отделения и эластичные карманы.', description_en = 'Gamma+ Barber Tool Bag — a compact bag for safely carrying and neatly storing barber tools. Impact-, water- and dust-resistant material, two inner compartments and elastic pockets.' where slug = 'barber-tool-bag';
update products set description_ru = 'Gamma+ Combs Set — набор из 6 профессиональных расчёсок для барберов. Прочный материал, антистатические свойства и удобство в работе — идеально для точной стрижки и укладки.', description_en = 'Gamma+ Combs Set — a set of 6 professional combs for barbers. Durable material, antistatic properties and comfortable handling make it ideal for precise cutting and styling.' where slug = 'combs-set';
update products set description_ru = 'Gamma+ Universal Curls & Waves Kit — универсальный набор для создания локонов с фенами. Поток воздуха на 360° автоматически закручивает волосы, создавая нежные волны и чёткие локоны. В комплекте 2 алюминиевых цилиндра и 3 переходных кольца.', description_en = 'Gamma+ Universal Curls & Waves Kit — a universal curling kit for hair dryers. 360° airflow automatically wraps the hair, creating soft waves and defined curls. The kit includes 2 aluminum cylinders and 3 adapter rings.' where slug = 'universal-curls-waves-kit';
select count(*) as with_ru_en from products where description_ru is not null and description_en is not null;
